 String suf(){return standby?"_s":"_a";} int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);} TextView tx(String s,int z){TextView t=new TextView(this);t.setText(s);t.setTextColor(Color.WHITE);t.setTextSize(z);return t;} Button bt(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);return b;} CheckBox cb(String s){CheckBox c=new CheckBox(this);c.setText(s);c.setTextColor(Color.WHITE);return c;} LinearLayout.LayoutParams mw(){return new LinearLayout.LayoutParams(-1,-2);} SeekBar slider(LinearLayout r,String s,int max){r.addView(tx(s,14),mw());SeekBar q=new SeekBar(this);q.setMax(max);r.addView(q,mw());return q;}
 @Override public void onCreate(Bundle b){super.onCreate(b);p=getSharedPreferences("ribaut_watch_designer",0);ScrollView sc=new ScrollView(this);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(dp(12),dp(10),dp(12),dp(24));r.setBackgroundColor(Color.rgb(18,18,22));sc.addView(r);TextView title=tx("Ribaut Watch Designer",22);title.setGravity(17);r.addView(title,mw());v=new WatchPreview(this);r.addView(v,new LinearLayout.LayoutParams(-1,dp(320)));
  LinearLayout prof=new LinearLayout(this);prof.setOrientation(LinearLayout.HORIZONTAL);actif=bt("ACTIF");veille=bt("VEILLE");prof.addView(actif,new LinearLayout.LayoutParams(0,-2,1));prof.addView(veille,new LinearLayout.LayoutParams(0,-2,1));r.addView(prof,mw());actif.setOnClickListener(x->sw(false));veille.setOnClickListener(x->sw(true));
  r.addView(tx("Élément à modifier",16),mw());edit=new Spinner(this);edit.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,edits));r.addView(edit,mw());selectedLabel=tx("Réglage : FOND",14);selectedLabel.setGravity(17);r.addView(selectedLabel,mw());TextView help=tx("Le choix ci-dessus détermine l'élément réglé • 1 doigt : déplacer • 2 doigts : zoomer",13);help.setGravity(17);r.addView(help,mw());
  r.addView(tx("Photos de fond",16),mw());Button ba=bt("Choisir photo ACTIF"),bs=bt("Choisir photo VEILLE");r.addView(ba,mw());r.addView(bs,mw());ba.setOnClickListener(x->{selectElement(0);pick(BG_A);});bs.setOnClickListener(x->{selectElement(0);pick(BG_S);});
  r.addView(tx("Aiguilles personnalisées (PNG transparent recommandé)",16),mw());LinearLayout hh=new LinearLayout(this);hh.setOrientation(LinearLayout.HORIZONTAL);Button h=bt("HEURES"),m=bt("MINUTES"),s=bt("SECONDES");hh.addView(h,new LinearLayout.LayoutParams(0,-2,1));hh.addView(m,new LinearLayout.LayoutParams(0,-2,1));hh.addView(s,new LinearLayout.LayoutParams(0,-2,1));r.addView(hh,mw());h.setOnClickListener(x->{selectElement(1);pick(HOUR);});m.setOnClickListener(x->{selectElement(2);pick(MIN);});s.setOnClickListener(x->{selectElement(3);pick(SEC);});
  testTimeLabel=tx("Heure de test des aiguilles : 12:00",14);r.addView(testTimeLabel,mw());testTime=new SeekBar(this);testTime.setMax(144);testTime.setProgress(0);r.addView(testTime,mw());TextView testHelp=tx("À 12:00, place sur la croix rouge le point de l'aiguille qui doit tourner. Cet emplacement devient automatiquement son axe de rotation. Puis déplace le curseur pour vérifier le mouvement.",12);r.addView(testHelp,mw());testTime.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar q,int n,boolean from){v.testMinutes=n*5;updateTestLabel();v.invalidate();}public void onStartTrackingTouch(SeekBar q){}public void onStopTrackingTouch(SeekBar q){}});
  r.addView(tx("Affichages",16),mw());mode=new Spinner(this);mode.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Analogique","Numérique"}));r.addView(mode,mw());digitalOverlay=cb("Afficher aussi l'heure numérique en mode analogique");r.addView(digitalOverlay,mw());Button editTime=bt("RÉGLER L'HEURE NUMÉRIQUE");r.addView(editTime,mw());editTime.setOnClickListener(x->selectElement(4));font=new Spinner(this);font.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Classique","Gras","Fin","Monospace","Serif"}));r.addView(font,mw());seconds=cb("Afficher les secondes");date=cb("Afficher la date");battery=cb("Afficher le pourcentage batterie");heart=cb("Afficher le cœur / BPM");r.addView(seconds,mw());r.addView(date,mw());r.addView(battery,mw());r.addView(heart,mw());LinearLayout infos=new LinearLayout(this);infos.setOrientation(LinearLayout.HORIZONTAL);Button ed=bt("DATE"),eb=bt("BATTERIE"),eh=bt("CŒUR");infos.addView(ed,new LinearLayout.LayoutParams(0,-2,1));infos.addView(eb,new LinearLayout.LayoutParams(0,-2,1));infos.addView(eh,new LinearLayout.LayoutParams(0,-2,1));r.addView(infos,mw());ed.setOnClickListener(x->selectElement(5));eb.setOnClickListener(x->selectElement(6));eh.setOnClickListener(x->selectElement(7));
  bg=slider(r,"Luminosité du fond",100);fg=slider(r,"Luminosité informations",100);size=slider(r,"Taille de l'élément sélectionné",500);Button center=bt("Recentrer l'élément sélectionné");r.addView(center,mw());center.setOnClickListener(x->{v.resetSelected();saveTransform();syncSize();});Button save=bt("ENREGISTRER");r.addView(save,mw());save.setOnClickListener(x->{save();Toast.makeText(this,"Projet enregistré",Toast.LENGTH_SHORT).show();});Button install=bt("INSTALLER SUR LA WATCH 8");r.addView(install,mw());install.setOnClickListener(x->new AlertDialog.Builder(this).setTitle("Installation Watch 8").setMessage("La liaison d'installation vers la montre est en cours d'intégration sur cette branche de test.").setPositiveButton("OK",null).show());
  edit.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?>a,View z,int n,long id){if(loading)return;v.selected=n;loadSelectedTransform();selectedLabel.setText("Réglage : "+edits[n]);syncSize();v.invalidate();}public void onNothingSelected(AdapterView<?>a){}});SeekBar.OnSeekBarChangeListener sl=new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar q,int n,boolean f){if(loading)return;if(q==size){v.zoom[v.selected]=Math.max(.25f,n/100f);saveTransform();}apply();}public void onStartTrackingTouch(SeekBar q){}public void onStopTrackingTouch(SeekBar q){save();}};bg.setOnSeekBarChangeListener(sl);fg.setOnSeekBarChangeListener(sl);size.setOnSeekBarChangeListener(sl);View.OnClickListener cl=x->{save();apply();};seconds.setOnClickListener(cl);date.setOnClickListener(cl);battery.setOnClickListener(cl);heart.setOnClickListener(cl);digitalOverlay.setOnClickListener(cl);mode.setOnItemSelectedListener(simple());font.setOnItemSelectedListener(simple());setContentView(sc);load(); }
 void selectElement(int n){if(n<0||n>=edits.length)return;edit.setSelection(n);v.selected=n;loadSelectedTransform();selectedLabel.setText("Réglage : "+edits[n]);if(n>=1&&n<=3){testTime.setProgress(0);v.testMinutes=0;updateTestLabel();}syncSize();v.invalidate();}
 void syncSize(){loading=true;size.setProgress(Math.min(size.getMax(),Math.round(v.zoom[v.selected]*100)));loading=false;}
 void updateTestLabel(){int mins=v.testMinutes;int hh=12+mins/60,mm=mins%60;if(hh>=24){hh=24;mm=0;}testTimeLabel.setText(String.format(Locale.FRANCE,"Heure de test des aiguilles : %02d:%02d",hh,mm));}
 AdapterView.OnItemSelectedListener simple(){return new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?>a,View x,int n,long id){if(!loading){save();apply();}}public void onNothingSelected(AdapterView<?>a){}};}
 void pick(int code){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("image/*");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,code);}
 @Override protected void onActivityResult(int rq,int rc,Intent d){super.onActivityResult(rq,rc,d);if(rc!=RESULT_OK||d==null||d.getData()==null)return;Uri u=d.getData();try{getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception e){}String k=null;if(rq==BG_A){k="background_uri_a";standby=false;selectElement(0);}else if(rq==BG_S){k="background_uri_s";standby=true;selectElement(0);}else if(rq==HOUR){k="hour_uri"+suf();selectElement(1);}else if(rq==MIN){k="minute_uri"+suf();selectElement(2);}else if(rq==SEC){k="second_uri"+suf();selectElement(3);}if(k!=null)p.edit().putString(k,u.toString()).apply();load();}
 void sw(boolean s){save();standby=s;load();}
 void load(){loading=true;String x=suf();bg.setProgress(p.getInt("bg"+x,standby?35:80));fg.setProgress(p.getInt("fg"+x,standby?45:100));seconds.setChecked(p.getBoolean("seconds"+x,!standby));date.setChecked(p.getBoolean("date"+x,true));battery.setChecked(p.getBoolean("battery"+x,true));heart.setChecked(p.getBoolean("heart"+x,false));digitalOverlay.setChecked(p.getBoolean("digitalOverlay"+x,false));mode.setSelection(p.getInt("mode"+x,0));font.setSelection(p.getInt("font"+x,1));actif.setEnabled(standby);veille.setEnabled(!standby);v.loadBg(uri(standby?"background_uri_s":"background_uri_a"));v.loadHand(0,uri("hour_uri"+x));v.loadHand(1,uri("minute_uri"+x));v.loadHand(2,uri("second_uri"+x));for(int i=0;i<8;i++)loadTransform(i);selectedLabel.setText("Réglage : "+edits[v.selected]);loading=false;syncSize();apply();}
 Uri uri(String k){String u=p.getString(k,null);return u==null?null:Uri.parse(u);} void loadTransform(int i){String x=suf()+"_"+i;v.zoom[i]=p.getFloat("z"+x,1f);v.ox[i]=p.getFloat("x"+x,0f);v.oy[i]=p.getFloat("y"+x,0f);}void loadSelectedTransform(){loadTransform(v.selected);}void saveTransform(){String x=suf()+"_"+v.selected;p.edit().putFloat("z"+x,v.zoom[v.selected]).putFloat("x"+x,v.ox[v.selected]).putFloat("y"+x,v.oy[v.selected]).apply();}
 void save(){if(loading)return;String x=suf();p.edit().putInt("bg"+x,bg.getProgress()).putInt("fg"+x,fg.getProgress()).putBoolean("seconds"+x,seconds.isChecked()).putBoolean("date"+x,date.isChecked()).putBoolean("battery"+x,battery.isChecked()).putBoolean("heart"+x,heart.isChecked()).putBoolean("digitalOverlay"+x,digitalOverlay.isChecked()).putInt("mode"+x,mode.getSelectedItemPosition()).putInt("font"+x,font.getSelectedItemPosition()).apply();saveTransform();}
 void apply(){v.digital=mode.getSelectedItemPosition()==1;v.digitalOverlay=digitalOverlay.isChecked();v.showSeconds=seconds.isChecked();v.showDate=date.isChecked();v.showBattery=battery.isChecked();v.showHeart=heart.isChecked();v.bgAlpha=bg.getProgress();v.fgAlpha=fg.getProgress();v.font=font.getSelectedItemPosition();v.invalidate();}
 public class WatchPreview extends View{Paint q=new Paint(3);Bitmap background;Bitmap[] hands=new Bitmap[3];int selected=0,bgAlpha=80,fgAlpha=100,font=1,testMinutes=0;boolean digital,digitalOverlay,showSeconds=true,showDate=true,showBattery=true,showHeart=false;float[] zoom=new float[8],ox=new float[8],oy=new float[8];float lx,ly,dist;
  WatchPreview(Context c){super(c);Arrays.fill(zoom,1f);setLayerType(View.LAYER_TYPE_SOFTWARE,null);post(tick);}Runnable tick=new Runnable(){public void run(){invalidate();postDelayed(this,1000);}};Bitmap dec(Uri u){if(u==null)return null;try(InputStream in=getContentResolver().openInputStream(u)){return BitmapFactory.decodeStream(in);}catch(Exception e){return null;}}void loadBg(Uri u){background=dec(u);}void loadHand(int i,Uri u){hands[i]=dec(u);}Typeface tf(){switch(font){case 1:return Typeface.DEFAULT_BOLD;case 2:return Typeface.create("sans-serif-light",0);case 3:return Typeface.MONOSPACE;case 4:return Typeface.SERIF;default:return Typeface.DEFAULT;}}
  void resetSelected(){zoom[selected]=1;ox[selected]=oy[selected]=0;invalidate();}
  boolean handEditing(){return selected>=1&&selected<=3;}
  @Override public boolean onTouchEvent(MotionEvent e){getParent().requestDisallowInterceptTouchEvent(true);int a=e.getActionMasked();if(a==MotionEvent.ACTION_DOWN){lx=e.getX();ly=e.getY();return true;}if(a==MotionEvent.ACTION_POINTER_DOWN&&e.getPointerCount()>1){dist=d(e);return true;}if(a==MotionEvent.ACTION_MOVE){if(e.getPointerCount()>1){float nd=d(e);if(dist>5){zoom[selected]=Math.max(.25f,Math.min(5f,zoom[selected]*nd/dist));loading=true;size.setProgress(Math.min(size.getMax(),Math.round(zoom[selected]*100)));loading=false;}dist=nd;}else{float dx=e.getX()-lx,dy=e.getY()-ly;ox[selected]=Math.max(-1,Math.min(1,ox[selected]+dx/getWidth()));oy[selected]=Math.max(-1,Math.min(1,oy[selected]+dy/getHeight()));lx=e.getX();ly=e.getY();}invalidate();return true;}if(a==MotionEvent.ACTION_UP||a==MotionEvent.ACTION_CANCEL){saveTransform();getParent().requestDisallowInterceptTouchEvent(false);return true;}return true;}float d(MotionEvent e){float x=e.getX(0)-e.getX(1),y=e.getY(0)-e.getY(1);return (float)Math.sqrt(x*x+y*y);}
  @Override protected void onDraw(Canvas c){float cx=getWidth()/2f,cy=getHeight()/2f,r=Math.min(getWidth(),getHeight())/2f-10;Path clip=new Path();clip.addCircle(cx,cy,r,Path.Direction.CW);c.save();c.clipPath(clip);q.setColor(Color.BLACK);q.setAlpha(255);c.drawCircle(cx,cy,r,q);drawBg(c,cx,cy,r);Date now=new Date();if(digital)drawText(c,new SimpleDateFormat(showSeconds?"HH:mm:ss":"HH:mm",Locale.FRANCE).format(now),4,cx,cy,r*.32f);else{drawAnalog(c,cx,cy,r);if(digitalOverlay)drawText(c,new SimpleDateFormat(showSeconds?"HH:mm:ss":"HH:mm",Locale.FRANCE).format(now),4,cx,cy-r*.30f,r*.20f);}if(showDate)drawText(c,new SimpleDateFormat("EEE dd MMM",Locale.FRANCE).format(now).replace(".",""),5,cx,cy+r*.55f,r*.11f);if(showBattery){BatteryManager bm=(BatteryManager)getSystemService(BATTERY_SERVICE);int n=bm==null?-1:bm.getIntProperty(BatteryManager.BATTERY_PROPERTY_CAPACITY);drawText(c,(n<0?"--":n)+"%",6,cx,cy+r*.72f,r*.11f);}if(showHeart)drawText(c,"♥ 72 bpm",7,cx,cy-r*.62f,r*.11f);if(handEditing())drawCenterMark(c,cx,cy,r);c.restore();q.setStyle(Paint.Style.STROKE);q.setStrokeWidth(4);q.setColor(Color.GRAY);q.setAlpha(255);c.drawCircle(cx,cy,r,q);q.setStyle(Paint.Style.FILL);}
  void drawBg(Canvas c,float cx,float cy,float r){if(background==null)return;float sc=Math.max(2*r/background.getWidth(),2*r/background.getHeight())*zoom[0];float w=background.getWidth()*sc,h=background.getHeight()*sc;float x=cx-w/2+ox[0]*2*r,y=cy-h/2+oy[0]*2*r;q.setAlpha((int)(bgAlpha*2.55f));c.drawBitmap(background,null,new RectF(x,y,x+w,y+h),q);}
  void drawAnalog(Canvas c,float cx,float cy,float r){float[] ang=new float[3];if(handEditing()){float total=12*60+testMinutes;float hour=(total/60f)%12f,minute=total%60f;ang[0]=hour*30f;ang[1]=minute*6f;ang[2]=0f;}else{Calendar z=Calendar.getInstance();ang[0]=(z.get(Calendar.HOUR)+z.get(Calendar.MINUTE)/60f)*30;ang[1]=z.get(Calendar.MINUTE)*6;ang[2]=z.get(Calendar.SECOND)*6;}float[] len={.48f,.68f,.75f};float[] wid={9,6,2.5f};for(int i=0;i<3;i++){if(i==2&&!showSeconds)continue;int el=i+1;float bx=cx+ox[el]*2*r,by=cy+oy[el]*2*r;Bitmap b=hands[i];if(b==null){double a=Math.toRadians(ang[i]-90);q.setColor(Color.WHITE);q.setAlpha((int)(fgAlpha*2.55f));q.setStrokeWidth(wid[i]*zoom[el]);q.setStrokeCap(Paint.Cap.ROUND);c.drawLine(cx,cy,cx+(float)Math.cos(a)*r*len[i]*zoom[el],cy+(float)Math.sin(a)*r*len[i]*zoom[el],q);}else{float target=r*len[i]*zoom[el],sc=target/Math.max(1,b.getHeight()),w=b.getWidth()*sc,h=b.getHeight()*sc;c.save();c.rotate(ang[i],cx,cy);q.setAlpha((int)(fgAlpha*2.55f));c.drawBitmap(b,null,new RectF(bx-w/2,by-h*.85f,bx+w/2,by+h*.15f),q);c.restore();}}}
  void drawCenterMark(Canvas c,float cx,float cy,float r){q.setAlpha(255);q.setStrokeWidth(Math.max(2f,r*.015f));q.setColor(Color.RED);float a=r*.07f;c.drawLine(cx-a,cy,cx+a,cy,q);c.drawLine(cx,cy-a,cx,cy+a,q);q.setColor(Color.WHITE);c.drawCircle(cx,cy,Math.max(3f,r*.018f),q);q.setStyle(Paint.Style.STROKE);q.setStrokeWidth(Math.max(2f,r*.012f));q.setColor(Color.RED);c.drawCircle(cx,cy,r*.035f,q);q.setStyle(Paint.Style.FILL);}
  void drawText(Canvas c,String s,int el,float bx,float by,float base){float r=Math.min(getWidth(),getHeight())/2f-10;float x=bx+ox[el]*2*r,y=by+oy[el]*2*r;q.setTextAlign(Paint.Align.CENTER);q.setTypeface(tf());q.setTextSize(base*zoom[el]);q.setColor(Color.WHITE);q.setAlpha((int)(fgAlpha*2.55f));q.setStyle(Paint.Style.FILL);c.drawText(s,x,y,q);}
 }
